import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import path from 'node:path';
import * as Effect from './apps/server/node_modules/effect/dist/Effect.js';
import * as Clock from './apps/server/node_modules/effect/dist/Clock.js';
import * as NodeFileSystem from './apps/server/node_modules/@effect/platform-node/dist/NodeFileSystem.js';
import * as NodePath from './apps/server/node_modules/@effect/platform-node/dist/NodePath.js';
import { pruneExpiredEntryFiles } from './apps/server/src/pullRequest/PullRequestReadCache.ts';
const directory = await fs.mkdtemp(path.join(process.cwd(), '.pr-cache-check-'));
try {
  const now = 1800000000000;
  const cutoff = now - 86400000;
  const expired = 'pr-v2' + 'a'.repeat(64);
  const fresh = 'pr-v2' + 'b'.repeat(64);
  const boundary = 'pr-v2' + 'c'.repeat(64);
  const future = 'pr-v2' + 'd'.repeat(64);
  const emptyDir = 'pr-v2' + 'e'.repeat(64);
  const nestedDir = 'pr-v2' + 'f'.repeat(64);
  const unrelated = ['revisions', 'notes.txt', 'pr-v2', 'pr-v2-notes', 'pr-v2' + '0'.repeat(63), 'pr-v2' + '0'.repeat(65), 'pr-v2' + 'G'.repeat(64), expired + '.bak', expired + '\\n'];
  for (const name of [expired, fresh, boundary, future, ...unrelated]) {
    const entry = path.join(directory, name);
    await fs.writeFile(entry, 'preserve content');
    const time = name === fresh ? now : name === boundary ? cutoff : name === future ? now + 86400000 : cutoff - 1000;
    await fs.utimes(entry, time / 1000, time / 1000);
  }
  for (const name of [emptyDir, nestedDir, 'pr-v2-unrelated-directory']) {
    const entry = path.join(directory, name);
    await fs.mkdir(entry);
    if (name === nestedDir) await fs.writeFile(path.join(entry, 'keep.txt'), 'nested content');
    await fs.utimes(entry, (cutoff - 1000) / 1000, (cutoff - 1000) / 1000);
  }
  await Effect.runPromise(Effect.gen(function* () {
    const clock = yield* Clock.Clock;
    yield* pruneExpiredEntryFiles(directory).pipe(Effect.provideService(Clock.Clock, { ...clock, currentTimeMillis: Effect.succeed(now), currentTimeMillisUnsafe: () => now }));
  }).pipe(Effect.provide(NodeFileSystem.layer), Effect.provide(NodePath.layer)));
  const names = await fs.readdir(directory);
  assert("'!names.includes(expired), '"'expired real entry removed');
  assert.equal(names.length, 3 + unrelated.length + 3);
  for (const name of [fresh, boundary, future, ...unrelated]) assert.equal(await fs.readFile(path.join(directory, name), 'utf8'), 'preserve content');
  for (const name of [emptyDir, nestedDir, 'pr-v2-unrelated-directory']) assert((await fs.stat(path.join(directory, name))).isDirectory());
  assert.equal(await fs.readFile(path.join(directory, nestedDir, 'keep.txt'), 'utf8'), 'nested content');
  console.log('Filesystem pruning checks passed: expired entry removed; fresh, boundary, future entries, unrelated files, and directories preserved.');
} finally {
  await fs.rm(directory, { recursive: true, force: true });
}
